"""DMGHG Native Loopback Bridge Service for HikerView PC Runtime.

Provides headless RPC integration with the installed Windows application
without launching desktop GUI or modifying application directories.
"""
import argparse
import ctypes
import json
import os
from pathlib import Path
import sys
import tempfile
import threading
import time
from urllib.parse import urlsplit, parse_qs
from http.server import ThreadingHTTPServer, BaseHTTPRequestHandler


class Bridge:
    """Headless C ABI bridge interacting with installed electron_bridge.dll."""

    READ_COMMANDS = {
        "app.ping",
        "catalog.get_channels",
        "catalog.get_banners",
        "catalog.get_video_list",
        "catalog.search_video",
        "catalog.get_video_key",
        "catalog.get_video_detail",
        "catalog.get_channel_detail",
        "video.play",
    }

    def __init__(self, app_dir):
        if os.name != "nt":
            raise RuntimeError("The installed bridge requires Windows x64 Python")
        self.app_dir = Path(app_dir).resolve(strict=True)
        self.dll_path = self.app_dir / "electron_bridge.dll"
        if not self.dll_path.is_file():
            raise RuntimeError("electron_bridge.dll is missing from the selected application directory")
        self.state_root = Path(tempfile.mkdtemp(prefix="dmghg-headless-"))
        os.environ["DMGHG_TEST_DATA_ROOT"] = str(self.state_root)
        os.environ["RUST_LOG"] = "error"
        self.dll = ctypes.CDLL(str(self.dll_path))
        self.dll.dmghg_service_new.argtypes = [ctypes.c_char_p, ctypes.c_char_p]
        self.dll.dmghg_service_new.restype = ctypes.c_void_p
        self.dll.dmghg_service_handle_command_json.argtypes = [ctypes.c_void_p, ctypes.c_char_p]
        self.dll.dmghg_service_handle_command_json.restype = ctypes.c_void_p
        self.dll.dmghg_string_free.argtypes = [ctypes.c_void_p]
        self.dll.dmghg_service_free.argtypes = [ctypes.c_void_p]
        self.lock = threading.RLock()
        self.version = installed_version(self.app_dir / "dmghg.exe")
        self.handle = self.dll.dmghg_service_new(b"dmghg-flutter", self.version.encode("ascii"))
        if not self.handle:
            raise RuntimeError("The installed bridge service could not initialize")

    def call(self, command, payload=None):
        if command not in self.READ_COMMANDS:
            raise ValueError(f"Command '{command}' is outside the read allowlist")
        request = {
            "request_id": f"bridge-{int(time.time() * 1000)}",
            "protocol_version": 1,
            "command": command,
            "payload": payload or {}
        }
        with self.lock:
            previous = Path.cwd()
            try:
                # Lua resolver searches resources/lua relative to Cwd
                os.chdir(self.app_dir)
                ptr = self.dll.dmghg_service_handle_command_json(
                    self.handle, json.dumps(request, ensure_ascii=False).encode("utf-8")
                )
                if not ptr:
                    raise RuntimeError("Bridge returned a null response")
                try:
                    response = json.loads(ctypes.string_at(ptr).decode("utf-8"))
                finally:
                    self.dll.dmghg_string_free(ptr)
            finally:
                os.chdir(previous)
        if response.get("ok") is not True:
            error = response.get("error", {})
            raise RuntimeError(f"{error.get('code', 500)}: {error.get('message', 'Unknown error')}")
        return response.get("data")

    def close(self):
        with self.lock:
            if self.handle:
                self.dll.dmghg_service_free(self.handle)
                self.handle = None


def installed_version(exe):
    """Read PE version metadata from target exe."""
    version = ctypes.windll.version
    size = version.GetFileVersionInfoSizeW(str(exe), None)
    if not size:
        raise RuntimeError("Cannot read application version metadata size")
    buffer = ctypes.create_string_buffer(size)
    if not version.GetFileVersionInfoW(str(exe), 0, size, buffer):
        raise RuntimeError("Cannot read application version info")
    info = ctypes.c_void_p()
    length = ctypes.c_uint()
    if not version.VerQueryValueW(buffer, "\\", ctypes.byref(info), ctypes.byref(length)):
        raise RuntimeError("Application version structure is missing")
    fields = ctypes.cast(info, ctypes.POINTER(ctypes.c_uint32))
    if fields[0] != 0xFEEF04BD or length.value < 52:
        raise RuntimeError("Application version structure is invalid")
    return f"{fields[2] >> 16}.{fields[2] & 65535}.{fields[3] >> 16}"


class BridgeHandler(BaseHTTPRequestHandler):
    """Loopback HTTP request handler for Hiker rule consumption."""
    timeout = 8.0
    server_version = "DMGHGBridge/1.0"

    def do_OPTIONS(self):
        self.send_response(204)
        self.send_cors_headers()
        self.end_headers()

    def send_cors_headers(self):
        self.send_header("Access-Control-Allow-Origin", "*")
        self.send_header("Access-Control-Allow-Methods", "GET, POST, OPTIONS")
        self.send_header("Access-Control-Allow-Headers", "Content-Type")

    def send_json(self, status_code, data):
        body = json.dumps(data, ensure_ascii=False).encode("utf-8")
        self.send_response(status_code)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        self.send_cors_headers()
        self.end_headers()
        self.wfile.write(body)

    def send_error_json(self, status_code, message, code=None):
        self.send_json(status_code, {
            "ok": False,
            "error": {
                "code": code or status_code,
                "message": str(message)
            }
        })

    def do_GET(self):
        parsed = urlsplit(self.path)
        path = parsed.path.rstrip("/")
        if not path:
            path = "/"
        query = parse_qs(parsed.query)

        try:
            if path in ("/ping", "/api/ping"):
                self.send_json(200, {
                    "ok": True,
                    "data": {
                        "service": "dmghg-bridge",
                        "status": "ready",
                        "version": self.server.bridge.version
                    }
                })
            elif path in ("/channels", "/catalog/channels", "/api/channels", "/video/channels"):
                data = self.server.bridge.call("catalog.get_channels")
                self.send_json(200, {"ok": True, "data": data})
            elif path in ("/video/list", "/catalog/video_list", "/api/list"):
                page_str = query.get("page", ["1"])[0]
                channel_str = query.get("channel", [None])[0]
                payload = {"page": int(page_str)}
                if channel_str is not None and channel_str != "":
                    payload["channel"] = int(channel_str)
                data = self.server.bridge.call("catalog.get_video_list", payload)
                self.send_json(200, {"ok": True, "data": data})
            elif path in ("/video/search", "/catalog/search_video", "/api/search"):
                key = query.get("key", [""])[0]
                page_str = query.get("page", ["1"])[0]
                data = self.server.bridge.call("catalog.search_video", {"key": key, "page": str(page_str)})
                self.send_json(200, {"ok": True, "data": data})
            elif path in ("/video/detail", "/catalog/video_detail", "/api/detail"):
                vid = query.get("id", [""])[0]
                if not vid:
                    self.send_error_json(400, "Missing required parameter 'id'")
                    return
                data = self.server.bridge.call("catalog.get_video_detail", {"id": str(vid)})
                self.send_json(200, {"ok": True, "data": data})
            elif path in ("/video/play", "/video/play_url", "/api/play"):
                vid = query.get("id", [""])[0]
                part = query.get("part", [""])[0]
                play = query.get("play", [""])[0]
                if not vid or not part:
                    self.send_error_json(400, "Missing required parameters 'id' or 'part'")
                    return
                payload = {
                    "id": str(vid),
                    "part": part,
                    "play": play,
                    "resolve": True
                }
                data = self.server.bridge.call("video.play", payload)
                self.send_json(200, {"ok": True, "data": data})
            else:
                self.send_error_json(404, f"Path '{path}' not found")
        except ValueError as e:
            self.send_error_json(403, str(e), 403)
        except Exception as e:
            self.send_error_json(500, str(e), 500)

    def do_POST(self):
        parsed = urlsplit(self.path)
        path = parsed.path.rstrip("/")
        if not path:
            path = "/"

        content_len_header = self.headers.get("Content-Length")
        if not content_len_header:
            self.send_error_json(411, "Length Required")
            return
        try:
            content_length = int(content_len_header)
        except ValueError:
            self.send_error_json(400, "Invalid Content-Length")
            return

        if content_length > 1024 * 1024:
            self.send_error_json(413, "Payload Too Large")
            return

        try:
            body_bytes = self.rfile.read(content_length)
            body = json.loads(body_bytes.decode("utf-8")) if body_bytes else {}
        except Exception as e:
            self.send_error_json(400, f"Malformed JSON body: {e}")
            return

        try:
            if path in ("/call", "/api/call"):
                command = body.get("command")
                payload = body.get("payload", {})
                if not command:
                    self.send_error_json(400, "Missing required field 'command'")
                    return
                if command not in Bridge.READ_COMMANDS:
                    self.send_error_json(403, f"Command '{command}' is not in the read allowlist", 403)
                    return
                data = self.server.bridge.call(command, payload)
                self.send_json(200, {"ok": True, "data": data})
            elif path in ("/video/play", "/api/play"):
                vid = body.get("id")
                part = body.get("part")
                play = body.get("play", "")
                if not vid or not part:
                    self.send_error_json(400, "Missing required fields 'id' or 'part'")
                    return
                payload = {
                    "id": str(vid),
                    "part": str(part),
                    "play": str(play),
                    "resolve": True
                }
                data = self.server.bridge.call("video.play", payload)
                self.send_json(200, {"ok": True, "data": data})
            else:
                self.send_error_json(404, f"Path '{path}' not found")
        except ValueError as e:
            self.send_error_json(403, str(e), 403)
        except Exception as e:
            self.send_error_json(500, str(e), 500)


class SafeThreadingServer(ThreadingHTTPServer):
    allow_reuse_address = True
    daemon_threads = True

    def __init__(self, server_address, RequestHandlerClass, bridge):
        super().__init__(server_address, RequestHandlerClass)
        self.bridge = bridge


def main():
    parser = argparse.ArgumentParser(description="DMGHG Local Loopback Bridge Service")
    parser.add_argument("--app-dir", default=r"D:\太极\动漫共和国概念版", help="Path to installed application directory")
    parser.add_argument("--port", type=int, default=18002, help="Loopback port to listen on (e.g. 18000, 18001, 18002)")
    parser.add_argument("--host", default="127.0.0.1", help="Loopback host address (default 127.0.0.1)")
    args = parser.parse_args()

    bridge = Bridge(args.app_dir)
    server = SafeThreadingServer((args.host, args.port), BridgeHandler, bridge)
    print(f"DMGHG Bridge running on [REDACTED_URL]")
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        server.server_close()
        bridge.close()


if __name__ == "__main__":
    main()

